import hashlib

def checksum_file(path: str, algorithm: str = "sha256") -> str:
    """Return hex digest of file using the given hash algorithm."""
    h = hashlib.new(algorithm)
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()
