import time, psutil

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    logs = []
    try:
        while True:
            now = time.time()
            for c in psutil.net_connections(kind='inet'):
                if c.raddr and c.laddr.ip == host and c.status == 'ESTABLISHED':
                    logs.append({'timestamp': now, 'source': f"{c.raddr.ip}:{c.raddr.port}"})
            time.sleep(interval_s)
    except KeyboardInterrupt:
        pass
    return logs
