import pyshark
import re
from collections import Counter

# simple DGA regex (random-looking)
DGA_REGEX = re.compile(r'^[a-z0-9]{12,}$', re.I)

def is_suspicious(domain: str) -> str:
    # DGA detection
    if DGA_REGEX.match(domain):
        return "DGA"
    # length & entropy heuristics for tunneling/exfil
    if len(domain) > 50:
        return "tunneling"
    # common exfil patterns (base64)
    if re.fullmatch(r'(?:[A-Za-z0-9+/]{4}){2,}', domain):
        return "exfiltration"
    return ""

def analyze_dns_traffic(pcap_file: str) -> dict:
    cap = pyshark.FileCapture(pcap_file, display_filter='dns')
    results = Counter()
    for pkt in cap:
        try:
            qname = pkt.dns.qry_name.lower()
            reason = is_suspicious(qname)
            if reason:
                results[(qname, reason)] += 1
        except AttributeError:
            continue
    cap.close()
    # aggregate per reason
    summary = {"DGA": [], "tunneling": [], "exfiltration": []}
    for (domain, reason), cnt in results.items():
        summary[reason].append({"domain": domain, "count": cnt})
    return summary
