def harden_ssh_config(config_path: str) -> dict:
    """
    Analyzes an ssh_config/sshd_config file and returns recommendations
    for more secure settings.
    """
    recommendations = {}
    if not Path(config_path).is_file():
        return {"error": "File not found"}

    # default insecure values
    insecure = {
        "PasswordAuthentication": "yes",
        "PermitRootLogin": "yes",
        "PermitEmptyPasswords": "yes",
        "ChallengeResponseAuthentication": "yes",
        "UsePAM": "yes",
        "X11Forwarding": "yes",
        "AllowTcpForwarding": "yes",
        "GatewayPorts": "yes",
        "PermitUserEnvironment": "yes",
        "Ciphers": None,          # should be limited
        "MACs": None,             # should be limited
        "KexAlgorithms": None,    # should be limited
    }

    # read file
    with open(config_path) as f:
        lines = f.readlines()

    # parse key/value pairs (ignore comments)
    config = {}
    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        m = re.match(r'(\S+)\s+(.*)', line)
        if m:
            key, val = m.group(1), m.group(2).split('#')[0].strip()
            config[key] = val

    # evaluate each insecure setting
    for key, bad_val in insecure.items():
        cur = config.get(key)
        if cur is None:
            continue
        if bad_val is None:
            # check for weak algorithms list length
            if key in ("Ciphers", "MACs", "KexAlgorithms"):
                if len(cur.split(',')) > 5:  # arbitrary threshold
                    recommendations[key] = f"Restrict {key} to a short, strong list"
        else:
            if cur.lower() == bad_val:
                recommendations[key] = f"Set {key} to 'no' (or a safer alternative)"

    # additional checks
    if config.get("LogLevel", "").lower() not in ("info", "verbose", "debug"):
        recommendations["LogLevel"] = "Set LogLevel to INFO or higher for auditing"

    if config.get("AllowAgentForwarding", "").lower() == "yes":
        recommendations["AllowAgentForwarding"] = "Disable agent forwarding unless required"

    return recommendations
