#!/usr/bin/env python3
import os, gzip, shutil, time
from pathlib import Path

LOG_DIR = Path("/var/log/ikea")
ARCHIVE_DIR = LOG_DIR / "archive"
RETENTION_DAYS = 7

def rotate():
    for log in LOG_DIR.glob("*.log"):
        if log.is_file():
            ts = time.strftime("%Y%m%d%H%M%S")
            rotated = LOG_DIR / f"{log.stem}.{ts}.log"
            log.rename(rotated)

def archive():
    ARCHIVE_DIR.mkdir(exist_ok=True)
    cutoff = time.time() - RETENTION_DAYS * 86400
    for file in LOG_DIR.glob("*.log*"):
        if file.stat().st_mtime < cutoff and not file.suffix == ".gz":
            with open(file, "rb") as f_in, gzip.open(f"{file}.gz", "wb") as f_out:
                shutil.copyfileobj(f_in, f_out)
            file.unlink()
            shutil.move(f"{file}.gz", ARCHIVE_DIR / f"{file.name}.gz")

if __name__ == "__main__":
    rotate()
    archive()
